-- Function: public.fn_get_available_cover_teachers
-- Backup generated on 2026-11-11 09:04:43

CREATE OR REPLACE FUNCTION public.fn_get_available_cover_teachers(p_tenant_id uuid, p_branch_id uuid, p_classroom_id uuid, p_date date, p_start time without time zone, p_end time without time zone, p_exclude_event_id uuid DEFAULT NULL::uuid)  RETURNS TABLE(user_id uuid, display_name text, is_same_classroom boolean, is_on_leave boolean, busy_with text, covers_this_week integer, is_available boolean, reason text)  LANGUAGE sql  STABLE AS $function$     WITH branch_teachers AS (         SELECT DISTINCT ct.user_id         FROM classroom_teachers ct         JOIN classrooms c ON c.id = ct.classroom_id         WHERE ct.tenant_id = p_tenant_id AND c.branch_id = p_branch_id         UNION         SELECT uba.user_id         FROM user_branch_assignments uba         JOIN teachers t ON t.user_id = uba.user_id AND t.tenant_id = p_tenant_id         WHERE uba.tenant_id = p_tenant_id AND uba.branch_id = p_branch_id AND uba.revoked_at IS NULL     ),     info AS (         SELECT bt.user_id,                COALESCE(NULLIF(TRIM(COALESCE(u.first_name,'') || ' ' || COALESCE(u.last_name,'')), ''), u.email)::text AS display_name,                EXISTS (SELECT 1 FROM classroom_teachers x WHERE x.user_id = bt.user_id AND x.classroom_id = p_classroom_id) AS is_same_classroom,                EXISTS (SELECT 1 FROM staff_leaves sl JOIN teachers t ON t.id = sl.teacher_id                        WHERE t.user_id = bt.user_id AND sl.tenant_id = p_tenant_id                          AND sl.status = 'Approved' AND p_date BETWEEN sl.start_date AND sl.end_date) AS is_on_leave,                (SELECT e.title || ' ' || COALESCE(to_char(e.start_time,'HH24:MI'),'all day')                 FROM events e                 WHERE e.tenant_id = p_tenant_id AND e.organizer_id = bt.user_id AND e.event_date = p_date                   AND e.status <> 'Cancelled'                   AND (p_exclude_event_id IS NULL OR e.id <> p_exclude_event_id)                   AND COALESCE(e.start_time, '00:00'::time) < COALESCE(p_end, '23:59:59.999999'::time)                   AND COALESCE(e.end_time, '23:59:59.999999'::time) > COALESCE(p_start, '00:00'::time)                 LIMIT 1)::text AS busy_with,                (SELECT COUNT(*)::int FROM staff_leaves sl JOIN teachers t ON t.id = sl.substitute_teacher_id                 WHERE t.user_id = bt.user_id AND sl.tenant_id = p_tenant_id                   AND sl.start_date <= p_date + 6 AND sl.end_date >= p_date - 6) AS covers_this_week         FROM branch_teachers bt         JOIN users u ON u.id = bt.user_id         WHERE u.tenant_id = p_tenant_id     )     SELECT i.user_id, i.display_name, i.is_same_classroom, i.is_on_leave, i.busy_with, i.covers_this_week,            (NOT i.is_on_leave AND i.busy_with IS NULL) AS is_available,            CASE                WHEN i.is_on_leave THEN 'On approved leave'                WHEN i.busy_with IS NOT NULL THEN 'Leading: ' || i.busy_with                WHEN i.is_same_classroom THEN 'Co-teacher in this classroom — children know them'                ELSE 'Free branch teacher'            END     FROM info i     ORDER BY (NOT i.is_on_leave AND i.busy_with IS NULL) DESC, i.is_same_classroom DESC, i.covers_this_week ASC, i.display_name; $function$ ;
